// Static marketing pages (generated by site/build.mjs): fonts, styles, and the
// RPK viewer's drop zone on /open/ and /bn/open/. Must stay light: no wasm,
// no framework.
import "@fontsource-variable/inter";
import "@fontsource/hind-siliguri/400.css";
import "@fontsource/hind-siliguri/600.css";
import "@fontsource/hind-siliguri/700.css";
import "./site.css";
import "./pages.css";
import "./theme"; // the nav's light / dark toggle
import "./download"; // platform-matched download buttons
import "./pricing"; // the pricing page's taka/dollar and monthly/yearly switches
import { stashPendingLesson } from "./pending";

const LESSON_MIME = "application/vnd.rupok.lesson+zip";
const VIEWER = "/board/?view&pending=1";

const drop = document.querySelector<HTMLElement>("[data-drop]");
if (drop) {
  const input = drop.querySelector<HTMLInputElement>("[data-file]")!;
  const pick = drop.querySelector<HTMLButtonElement>("[data-pick]")!;
  const msg = drop.querySelector<HTMLElement>("[data-msg]")!;
  const t = (key: string, name = "") => (drop.dataset[key] ?? "").replaceAll("{name}", name);
  const say = (text: string, kind: "info" | "error" = "error", html = false) => {
    msg.dataset.kind = kind;
    if (html) msg.innerHTML = text; // our own markup from data-t-blocked
    else msg.textContent = text; // may contain the file name: never HTML
  };

  // Phones get every file in the picker: a custom extension in `accept` can
  // grey out the teacher's file on Android and iOS. Desktops filter to .rpk.
  if (matchMedia("(pointer: fine)").matches) input.accept = ".rpk";

  async function open(file: File) {
    if (!file.size) return say(t("tEmpty"));
    // A Rupok lesson is a ZIP whose first entry is `mimetype`, stored, holding
    // the media type (spec/rupok-format.md#package-layout).
    const head = new Uint8Array(await file.slice(0, 200).arrayBuffer());
    const zip = head[0] === 0x50 && head[1] === 0x4b && head[2] === 3 && head[3] === 4;
    const rupok = zip && new TextDecoder("latin1").decode(head).includes(LESSON_MIME);
    const named = /\.rpk$/i.test(file.name);
    if (!rupok && !(named && zip)) return say(t(named ? "tOther" : "tNotrpk", file.name));
    // WhatsApp and browsers sometimes rename downloads ("lesson.rpk.zip",
    // "lesson (1)"); the board opens files by extension.
    const name = named ? file.name : file.name.replace(/\.zip$/i, "").replace(/(\.rpk)?$/i, ".rpk");
    say(t("tOpening", name), "info");
    try {
      await stashPendingLesson(file, name);
      location.assign(VIEWER);
    } catch {
      say(t("tBlocked"), "error", true);
    }
  }

  pick.addEventListener("click", () => input.click());
  input.addEventListener("change", () => {
    const f = input.files?.[0];
    if (f) void open(f);
    input.value = "";
  });

  // Drop anywhere on the page; highlight the zone while dragging.
  let depth = 0;
  const hasFiles = (e: DragEvent) => Array.from(e.dataTransfer?.types ?? []).includes("Files");
  addEventListener("dragenter", (e) => {
    if (!hasFiles(e)) return;
    depth++;
    drop.classList.add("over");
  });
  addEventListener("dragleave", () => {
    if (--depth <= 0) {
      depth = 0;
      drop.classList.remove("over");
    }
  });
  addEventListener("dragover", (e) => {
    if (hasFiles(e)) e.preventDefault();
  });
  addEventListener("drop", (e) => {
    if (!hasFiles(e)) return;
    e.preventDefault();
    depth = 0;
    drop.classList.remove("over");
    const f = e.dataTransfer?.files[0];
    if (f) void open(f);
  });

  // Back from the viewer (bfcache): clear the "Opening…" message.
  addEventListener("pageshow", (e) => {
    if (e.persisted) say("", "info");
  });
}
